/**
 * Built-in number literal table.
 *
 * These are **encodings** (how to draw `num_<n>` on the staff), not registry
 * patterns: shipping them keeps `num_<n>` working without a connection.
 * Generated by `scripts/generate_patterns.py` from `scripts/data/numbers_2000.json`.
 * The same file is copied to `src/hexparse/data/` so it is bundled.
 */
import numbers from "./data/numbers_2000.json" with { type: "json" };

export const BUILTIN_NUMBERS = numbers as unknown as Record<
  string,
  [string, string]
>;
